28: template <int n>
29: struct TensorListMetadata {
30:     void* addresses[n][depth_to_max_tensors[n - 1]];
31:     int64_t sizes[depth_to_max_tensors[n - 1]];
32:     unsigned char block_to_tensor[depth_to_max_blocks[n - 1]];
