37: template <typename T, typename U, typename... ArgTypes>
38: __global__ void multi_tensor_apply_kernel(int64_t chunk_size,
39:                                           volatile int* noop_flag,
40:                                           T tl,
41:                                           U callable,
42:                                           ArgTypes... args)
43: {
44:     // Hand the chunk information to the user-supplied functor to process however it likes.
45:     callable(chunk_size, noop_flag, tl, args...);
46: }
